def add_text(p, text):
    for chunk in re.split(r'(\[\[[^]]+\]\])', text):
        if chunk.startswith('[[') and chunk.endswith(']]'):
            p.add_run(chunk[2:-2]).font.superscript = True
        elif chunk:
            p.add_run(chunk)

content = []
def paragraph(text, lead=None, style=None):
    text = text.replace('plasmode simulation. Each', 'plasmode simulation[[35]]. Each')
    text = text.replace('AACR GENIE BPC while', 'AACR GENIE BPC[[10]] while')
    text = text.replace('DepMap plasmodes will', 'DepMap plasmodes[[9,11,36–38]] will')
    after_table = len(doc._element.body) > 1 and doc._element.body[-2].tag == qn('w:tbl')
    p = doc.add_paragraph(style=style)
    p.paragraph_format.widow_control = True
    if after_table:
        p.paragraph_format.space_before = Pt(6)
    if lead:
        p.add_run(lead + ' ').bold = True
        add_text(p, text)
        content.append(lead + ' ' + text)
    else:
        add_text(p, text)
        content.append(text)
    return p

def heading(text):
    return paragraph(text, style='Heading 1')

def table(headers, rows, widths):
    t = doc.add_table(rows=1, cols=len(headers))
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    t.autofit = False
    for c, w in zip(t.columns, widths): c.width = Inches(w)
    for c, text in zip(t.rows[0].cells, headers): c.text = text
    for vals in rows:
        for c, text in zip(t.add_row().cells, vals): c.text = text
    props = t._tbl.tblPr
    borders = OxmlElement('w:tblBorders')
    for edge in ['top','left','bottom','right','insideH','insideV']:
        el=OxmlElement('w:'+edge)
        for k,v in [('val','single'),('sz','4'),('color','D9D9D9')]: el.set(qn('w:'+k),v)
        borders.append(el)
    props.append(borders)
    margins = OxmlElement('w:tblCellMar')
    for name, val in [('top','65'),('bottom','65'),('left','85'),('right','85')]:
        el = OxmlElement('w:'+name); el.set(qn('w:w'),val); el.set(qn('w:type'),'dxa'); margins.append(el)
    props.append(margins)
    for i,row in enumerate(t.rows):
        trpr=row._tr.get_or_add_trPr()
        trpr.append(OxmlElement('w:cantSplit'))
        if i==0: trpr.append(OxmlElement('w:tblHeader'))
        for c,w in zip(row.cells,widths):
            c.width=Inches(w)
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if i==0:
                shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),'E2EED9'); c._tc.get_or_add_tcPr().append(shd)
            for p in c.paragraphs:
                p.paragraph_format.space_after=Pt(0)
                p.paragraph_format.line_spacing=1
                for r in p.runs:
                    r.font.name='Arial'; r.font.size=Pt(10); r.font.color.rgb=RGBColor(0,0,0); r.bold=i==0
    content.append('\n'.join([' | '.join(headers)]+[' | '.join(r) for r in rows]))
    return t

